@extends('layouts.admin') @section('admin_content')<h1 class="section-title mb-7">{{$product?'Edit product':'New product'}}</h1><form class="card p-6" method="post" action="{{$product?route('admin.product.update',$product):route('admin.product.save')}}">@csrf<div class="form-grid"><div><label class="label">Name<input class="field" name="name" value="{{old('name',$product?->name)}}" required></label></div><div><label class="label">URL slug<input class="field" name="slug" value="{{old('slug',$product?->slug)}}" required></label></div><div><label class="label">Category<select class="field" name="category_id" required>@foreach($categories as $category)<option value="{{$category->id}}" @selected(old('category_id',$product?->category_id)==$category->id)>{{$category->name}}</option>@endforeach</select></label></div><div><label class="label">Collection<select class="field" name="collection_id"><option value="">None</option>@foreach($collections as $collection)<option value="{{$collection->id}}" @selected(old('collection_id',$product?->collection_id)==$collection->id)>{{$collection->name}}</option>@endforeach</select></label></div><div class="full"><label class="label">Description<textarea class="field min-h-36" name="description" required>{{old('description',$product?->description)}}</textarea></label></div><div class="full"><label class="label">Care instructions<textarea class="field" name="care">{{old('care',$product?->care)}}</textarea></label></div>@foreach(['material','colour','style','occasion'] as $field)<div><label class="label">{{ucfirst($field)}}<input class="field" name="{{$field}}" value="{{old($field,$product?->$field)}}"></label></div>@endforeach</div><label class="flex items-center gap-2 my-6"><input type="checkbox" name="published" value="1" @checked(old('published',$product?->published))> Publish product</label><h2 class="serif text-2xl mb-4">Variants</h2><p class="muted text-sm mb-4">Each SKU has its own price in paise and stock. Add another row for each size, colour or set.</p><div id="variants">@foreach(old('variants',$product?->variants->toArray() ?? [['sku'=>'','price_paise'=>0,'stock'=>0]]) as $index=>$variant)<div class="card p-4 mb-3 grid grid-cols-2 md:grid-cols-4 gap-3"><input type="hidden" name="variants[{{$index}}][id]" value="{{$variant['id']??''}}">@foreach(['sku'=>'SKU','size'=>'Size','colour'=>'Colour','material'=>'Material','set_size'=>'Set size','price_paise'=>'Price (paise)','stock'=>'Stock'] as $key=>$label)<label class="label">{{$label}}<input class="field" name="variants[{{$index}}][{{$key}}]" value="{{$variant[$key]??''}}" @if(in_array($key,['price_paise','stock'])) type="number" min="0" @endif @if(in_array($key,['sku','price_paise','stock'])) required @endif></label>@endforeach</div>@endforeach</div><button type="button" class="button button-light" onclick="addVariant()">Add variant</button><button class="button mt-5 block">Save product</button></form>@if($product)<div class="card p-6 mt-5"><h2 class="serif text-2xl mb-5">Images</h2><div class="grid grid-cols-2 md:grid-cols-4 gap-4">@foreach($product->images as $image)<div><img src="{{asset('storage/'.$image->path)}}" alt="{{$image->alt}}"><form method="post" action="{{route('admin.images.position',$image)}}">@csrf<input class="field mt-2" type="text" name="alt" value="{{$image->alt}}" aria-label="Image alt text"><input class="field mt-2" type="number" name="position" value="{{$image->position}}" aria-label="Image position"><button class="underline mt-2">Update</button></form><form method="post" action="{{route('admin.images.delete',$image)}}">@csrf @method('DELETE')<button class="underline">Delete</button></form></div>@endforeach</div><form method="post" enctype="multipart/form-data" action="{{route('admin.images.upload',$product)}}" class="mt-8">@csrf<label class="label">Upload images<input class="field" type="file" accept="image/png,image/jpeg,image/webp" name="images[]" multiple required></label><label class="label mt-3">Description for accessibility<input class="field" name="alt" required></label><button class="button mt-4">Upload</button></form></div>@endif @push('scripts')<script>let nextVariant=document.querySelectorAll('#variants>div').length;function addVariant(){let n=nextVariant++;let el=document.createElement('div');el.className='card p-4 mb-3 grid grid-cols-2 md:grid-cols-4 gap-3';for(const [key,label] of Object.entries({sku:'SKU',size:'Size',colour:'Colour',material:'Material',set_size:'Set size',price_paise:'Price (paise)',stock:'Stock'})){let wrap=document.createElement('label');wrap.className='label';wrap.textContent=label;let input=document.createElement('input');input.className='field';input.name=`variants[${n}][${key}]`;if(['stock','price_paise'].includes(key)){input.type='number';input.min='0'}if(['sku','stock','price_paise'].includes(key))input.required=true;wrap.appendChild(input);el.appendChild(wrap)}document.getElementById('variants').appendChild(el)}</script>@endpush @endsection
